    "questionEn": "[HOTS Analysis #10] Evaluating Geographical Distribution of Minorities and Separatism: Why is an ethnic minority concentrated along the peripheral mountainous borders of a state (such as the Basques in Spain or East Timor in Indonesia) significantly more dangerous to territorial integrity than a minority dispersed throughout the capital and urban core?",
    "questionAr": "[تحليل ونقد #10] في ضوء الموازنة في Geographical Distribution of Minorities and Separatism: لماذا يمثل استقرار الأقلية وتكتلها الجغرافي على أطراف الدولة وهوامشها الجبلية (كالباسك في إسبانيا وتيمور الشرقية بإندونيسيا) خطراً انفصالياً أكبر بكثير من انتشارها المبعثر في العاصمة والمدن الكبرى؟",
